import base64
import hashlib
import os
import secrets
import urllib.parse
from typing import Dict, Optional


class Auth0OIDCLogin:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        audience: Optional[str] = None,
    ) -> None:
        self.domain = (domain or os.environ["AUTH0_DOMAIN"]).strip()
        self.client_id = (client_id or os.environ["AUTH0_CLIENT_ID"]).strip()
        self.redirect_uri = (redirect_uri or os.environ["AUTH0_REDIRECT_URI"]).strip()
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")

        if self.domain.startswith("https://"):
            self.base_url = self.domain.rstrip("/")
        else:
            self.base_url = f"https://{self.domain.rstrip('/')}"

        self.authorization_endpoint = f"{self.base_url}/authorize"

    @staticmethod
    def _urlsafe_b64_no_padding(raw: bytes) -> str:
        return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")

    @classmethod
    def _generate_code_verifier(cls, length: int = 64) -> str:
        verifier = cls._urlsafe_b64_no_padding(secrets.token_bytes(length))
        return verifier[:128]

    @classmethod
    def _generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._urlsafe_b64_no_padding(digest)

    def start_login(
        self,
        scope: str = "openid profile email",
        connection: Optional[str] = None,
        organization: Optional[str] = None,
        prompt: Optional[str] = None,
    ) -> Dict[str, str]:
        state = secrets.token_urlsafe(32)
        nonce = secrets.token_urlsafe(32)
        code_verifier = self._generate_code_verifier()
        code_challenge = self._generate_code_challenge(code_verifier)

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": scope,
            "state": state,
            "nonce": nonce,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }

        if self.audience:
            params["audience"] = self.audience
        if connection:
            params["connection"] = connection
        if organization:
            params["organization"] = organization
        if prompt:
            params["prompt"] = prompt

        authorization_url = f"{self.authorization_endpoint}?{urllib.parse.urlencode(params)}"

        return {
            "provider": "Auth0",
            "authorization_url": authorization_url,
            "state": state,
            "nonce": nonce,
            "code_verifier": code_verifier,
        }
